#!/usr/bin/env python3
"""Черновики карточек 7–11 классов для игры «Мастерская роботов».
Решения для памятки учителя берутся из tests/.solutions.json (его пишет tests/solutions.gd -- dump)."""
import json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
src=(HERE/'levels.gd').read_text()
names=lambda const:json.loads(re.search(r'const '+const+r' := (\{.*?\})\n',src).group(1))
OPS,CONDS=names('OP_NAMES'),names('COND_NAMES')
ordered=json.loads((HERE/'tests/.solutions.json').read_text());sol={x['id']:x['program'] for x in ordered}
titles=dict(re.findall(r'"id": "([^"]+)", "title": "([^"]+)"',src))
def show(prog):
    out=[]
    for n in prog:
        t=OPS[n['op']].lower()
        if n['op']=='repeat':t+=' %d [%s]'%(n['n'],show(n['body']))
        elif n['op']=='while':t+=' %s [%s]'%(CONDS[n['cond']],show(n['body']))
        elif n['op']=='if':t+=' %s [%s]'%(CONDS[n['cond']],show(n['body']) or 'ничего')+(' иначе [%s]'%show(n['alt']) if n['alt'] else '')
        out.append(t)
    return ', '.join(out)
def blocks(prog):return sum(1+blocks(n.get('body',[]))+blocks(n.get('alt',[])) for n in prog)
SHOPS={
 7:('цех кодирования','Лампы — это биты. Запиши числа в двоичном коде, нарисуй растровую картинку по её коду, сделай негатив и передай код без ошибок.',['Записывать числа в двоичном коде и читать вес разрядов.','Кодировать растровое изображение построчно.','Обрабатывать код циклом с проверкой каждого бита.']),
 8:('электроцех','Собери логические элементы: НЕ, И, ИЛИ, исключающее ИЛИ, импликацию и полусумматор. Робот зажигает выход, глядя на входы A и B; проверяются все строки таблицы истинности.',['Строить таблицы истинности логических операций.','Выражать И, ИЛИ, НЕ через вложенные ветвления.','Собирать схему из нескольких логических элементов.']),
 9:('цех данных','Стеллаж с числами — это массив. Найди сумму, нужный элемент и максимум, а затем отсортируй числа обменами соседей.',['Обрабатывать массив циклом: сумма, поиск, максимум.','Использовать цикл с условием, когда длина массива неизвестна.','Понимать сортировку обменами.']),
 10:('вычислительный цех','Двоичная арифметика своими руками: прибавь и вычти единицу, получи дополнительный код, поставь бит чётности и собери сумматор с переносом.',['Выполнять сложение и вычитание в двоичной системе с переносом.','Объяснять дополнительный код и бит чётности.','Строить логическую функцию трёх переменных.']),
 11:('цех алгоритмов','Алгоритмы обработки массивов: нарастающий итог, счётчик, минимум, вставка в упорядоченный ряд, сортировка и разделение, как в быстрой сортировке.',['Составлять алгоритмы обработки массива с накоплением и счётчиком.','Объяснять шаг сортировки вставками и шаг быстрой сортировки.','Сравнивать решения по числу блоков.']),
}
for g,(name,desc,goals) in SHOPS.items():
    ids=[x['id'] for x in ordered if x['grade']==g]
    notes=['Игра на движке Godot, двенадцать заданий. Звёзды: одна за работающую программу, две и три — за короткую. Там, где данные случайные, программу проверяют три смены подряд.']
    notes+=['%d. %s — %d блоков: %s.'%(i+1,titles[k],blocks(sol[k]),show(sol[k])) for i,k in enumerate(ids)]
    notes.append('Решения не единственные. Прогресс хранится только в браузере этого компьютера; оценки в журнал не отправляются. Игра требует браузер с WebGL 2.')
    d={'schemaVersion':1,'kind':'game','gameMode':'godot','godotProject':'workshop','godotHost':'game-6-robot-workshop','slug':'game-%d-robot-workshop'%g,'grade':g,'subject':'Информатика',
       'title':'Кодоград: Мастерская роботов · '+name,'description':'Игра-головоломка: собери из блоков программу для робота. '+desc+' Двенадцать заданий; чем короче программа, тем больше звёзд.','durationMinutes':45,'goals':goals,
       'instructions':['Нажимайте блоки справа или клавиши с цифрами — блок встаёт на место жёлтого курсора.','Enter или кнопка «Пуск» запускают робота. Ошибка останавливает его и подсвечивает блок красным.','Игра сохраняет звёзды и программы в этом браузере. Отметки в журнал не отправляются.'],'teacherNotes':notes}
    d['movedTo']='/courses/game-%d-practicum/'%g  # старое меню цехов ведёт в практикум
    (ROOT/'drafts'/('game-%d-robot-workshop.json'%g)).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
    print(g,name,len(ids),'заданий')

# 6 класс — хозяин общей копии игры: паспорт написан вручную, обновляем только решения в памятке.
p6=ROOT/'drafts'/'game-6-robot-workshop.json';d6=json.loads(p6.read_text());ids6=[x['id'] for x in ordered if x['grade']==6]
d6['teacherNotes']=['Игра на движке Godot, двенадцать заданий цеха «Склад»: исполнитель и его команды, линейный алгоритм, цикл с числом повторений, вложенный цикл, ветвление, цикл с условием. Звёзды: одна за работающую программу, две и три — за короткую. Там, где данные или карта случайные, программу проверяют три смены подряд.']+['%d. %s — %d блоков: %s.'%(i+1,titles[k],blocks(sol[k]),show(sol[k])) for i,k in enumerate(ids6)]+['Решения не единственные. Отметка ставится со страницы «Игровой практикум»; на отдельной странице игры прогресс хранится только в браузере. Игра весит около 40 МБ и требует браузер с WebGL 2.']
d6['description']='Игра-головоломка: собери из блоков программу для робота-погрузчика и запусти его на складе. Двенадцать заданий: команды по порядку, циклы «повтори» и «пока», ветвление «если — иначе». Чем короче программа, тем больше звёзд.'
d6['durationMinutes']=45
p6.write_text(json.dumps(d6,ensure_ascii=False,indent=2)+'\n')

