    if g==9: topical.append(lab('autopilot','Автопилот','алгоритмы управления','🚁','#7fe3c8',8,40,'Полёт','Автопилот для дрона на Python: команды и датчики препятствий. Одна программа должна долететь на трёх разных картах — от коридоров до лабиринтов.'))
    if g in (10,11): topical.append(lab('ege','ЕГЭ-арена','подготовка к ЕГЭ','🏆','#ffb347',18,45,'Задание','Восемнадцать заданий ЕГЭ без компьютера: граф и таблица дорог, таблица истинности, код Фано, алгоритмы, Черепаха, объёмы, комбинаторика, Редактор, маски, системы счисления, ДЕЛ, рекурсия, игра с кучей камней, параллельные процессы, программы исполнителя.'))
    if g in (10,11): topical.append(lab('turing','Машина Тьюринга','теория алгоритмов','📼','#f0a1ff',8 if g==10 else 12,45,'Задача','Составь таблицу правил машины Тьюринга и смотри, как головка бежит по ленте. Программа проверяется на нескольких лентах: инверсия, двоичные +1 и −1, скобки'+(', сортировка, удвоение, палиндром и копия слова' if g==11 else '')+'.'))
    if 8<=g<=11: topical.append(lab('cipher','Шифровальня','защита информации','🔐','#6c8cff',10 if g<=9 else 12,45,'Задание','Шифр Цезаря на колесе, частотный анализ, скитала и перестановка столбцов, шифр Виженера и число ключей'+(', учебный RSA с открытым и закрытым ключом' if g>=10 else '')+'. Сообщения каждый раз новые, после ошибки — разбор.'))
